import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new ctx.THREE.Group();
  const primitives = [];
  const timelines = [];

  // Load GLB mesh
  let gltfScene = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    gltfScene = gltf.scene;
    root.add(gltfScene);
  });

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const p = ctx.primitives[prim.name](root, prim.params);
      primitives.push(p);
    }
  }

  // Event handlers container
  root.userData.handlers = {};

  // Hover effect: rise-in (translate up 0.15 units)
  const hoverEnter = () => {
    const tl = gsap.timeline();
    tl.to(root.position, { y: root.position.y + 0.15, duration: 0.15, ease: "power3.out" });
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.timeline();
    tl.to(root.position, { y: root.position.y - 0.15, duration: 0.15, ease: "power3.out" });
    timelines.push(tl);
  };
  root.userData.handlers.hover = { enter: hoverEnter, leave: hoverLeave };

  // Click effect: emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-features.select', {});
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose GLB resources
    if (gltfScene) {
      gltfScene.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }
    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
    // Cleanup primitives
    primitives.forEach((p) => {
      if (p && typeof p.cleanup === "function") p.cleanup();
    });
  };

  return root;
}
